import { useState, useEffect } from 'react';
import { Tick, Arrow } from './icons.jsx';
import { BASE } from '../../../api/seoApi';

/**
 * Fetches live from /payment/plans rather than hardcoding plan data here —
 * that endpoint is the single source of truth for both this marketing page
 * and the authenticated Billing page, so pricing shown here can never
 * drift from what a signup actually gets charged. Deliberately fetched
 * directly (not via paymentApi.getPlans()) since that wrapper's
 * getAuthHeaders() throws when no one is logged in — this section is
 * reached by unauthenticated visitors by definition.
 */
export default function Pricing({ onStartTrial, initialPlans }) {
  const [plans, setPlans] = useState(initialPlans || null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (initialPlans) return; // prerender already resolved this — skip the fetch entirely
    fetch(`${BASE}/payment/plans`)
      .then(res => res.ok ? res.json() : Promise.reject(new Error(`status ${res.status}`)))
      .then(data => setPlans(data.plans || []))
      .catch(() => setError(true)); // fails quiet - this section just won't render rather than showing a broken error box on the homepage
    // eslint-disable-next-line
  }, []);

  if (error || (plans && plans.length === 0)) return null;

  return (
    <section className="section" id="pricing">
      <div className="pricing-head">
        <div className="section-eyebrow"><span className="mono">05</span><span>Pricing</span></div>
        <h2 className="section-title">
          Pricing built around <em>how often you publish.</em>
        </h2>
        <p className="section-sub" style={{ margin: '20px auto 0', textAlign: 'center' }}>
          Every plan tracks your AI-search visibility and ships content automatically.
          Pick the cadence that matches your team.
        </p>
      </div>

      {!plans && <div className="plans-loading">Loading plans…</div>}

      {plans && plans.length > 0 && (
        <div className="plans">
          {plans.map((p) => (
            <article className={`plan ${p.highlight ? 'plan-hi' : ''}`} key={p.plan_id}>
              {p.highlight && <span className="plan-badge">Most popular</span>}
              <div className="plan-name">{p.name}</div>
              <div className="plan-prompts"><span>{p.prompts}</span> prompts / mo</div>
              <div className="plan-blurb">{p.blurb}</div>
              <div className="plan-price">
                <span className="plan-currency">{p.currency === 'USD' ? '$' : p.currency}</span>
                <span className="plan-amount">{Math.round(parseFloat(p.amount))}</span>
                <span className="plan-period">/ mo</span>
              </div>
              <div className="plan-cycle">billed annually</div>
              <ul className="plan-feats">
                {p.features.map((f) => <li key={f}><Tick /> <span>{f}</span></li>)}
              </ul>
              <button
                type="button"
                className={`btn ${p.highlight ? 'btn-primary' : 'btn-ghost'} btn-lg`}
                style={{ justifyContent: 'center', width: '100%' }}
                onClick={() => onStartTrial?.(p.plan_id)}
              >
                Start 14-day trial <Arrow className="btn-arrow" size={13} />
              </button>
            </article>
          ))}
        </div>
      )}

      <div className="plans-foot">
        Need SSO, SOC2, on-prem or volume pricing? <a href="#contact">Talk to sales →</a>
      </div>
    </section>
  );
}
